css:
/* =========================================================
   ARM — PREMIUM SALARY SLIP
   Black / White Corporate Design
   ERPNext 15
   ========================================================= */


/* =========================================================
   PAGE
   ========================================================= */

@page {
    size: A4;
    margin: 8mm;
}


/* =========================================================
   ROOT
   ========================================================= */

.arm-salary-slip {
    width: 100%;
    max-width: 190mm;
    margin: 0 auto;

    padding: 8mm 7mm 6mm 7mm;

    background: #ffffff;
    color: #111111;

    font-family:
        "Tahoma",
        "Segoe UI",
        Arial,
        sans-serif;

    font-size: 10px;
    line-height: 1.5;

    direction: rtl;

    box-sizing: border-box;

    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}


/* =========================================================
   RESET
   ========================================================= */

.arm-salary-slip *,
.arm-salary-slip *::before,
.arm-salary-slip *::after {
    box-sizing: border-box;
}

.arm-salary-slip table {
    border-collapse: collapse;
    border-spacing: 0;
}

.arm-salary-slip img {
    max-width: 100%;
}


/* =========================================================
   HEADER
   ========================================================= */

.arm-header {
    display: flex;
    align-items: center;
    justify-content: space-between;

    min-height: 82px;

    padding: 8px 0 14px 0;

    border-bottom: 2px solid #111111;
}


/* =========================================================
   BRAND
   ========================================================= */

.arm-brand {
    width: 55%;
    display: flex;
    align-items: center;
    justify-content: flex-start;
}


.arm-logo {
    display: block;

    width: 210px;
    max-width: 100%;
    height: auto;

    object-fit: contain;
}


/* =========================================================
   DOCUMENT TITLE
   ========================================================= */

.arm-document-title {
    width: 45%;

    text-align: left;

    padding-left: 3px;
}


.arm-document-title-ar {
    font-size: 21px;
    font-weight: 800;

    line-height: 1.2;

    color: #111111;

    margin-bottom: 2px;
}


.arm-document-title-en {
    font-size: 9px;
    font-weight: 700;

    letter-spacing: 1.7px;

    color: #777777;

    direction: ltr;
}


.arm-document-number {
    display: inline-block;

    margin-top: 7px;

    padding: 4px 9px;

    background: #111111;
    color: #ffffff;

    border-radius: 3px;

    font-size: 8.5px;
    font-weight: 700;

    direction: ltr;

    white-space: nowrap;
}


/* =========================================================
   PERIOD BAR
   ========================================================= */

.arm-period-bar {
    display: flex;

    margin-top: 14px;

    border: 1px solid #dedede;

    background: #f8f8f8;

    border-radius: 5px;

    overflow: hidden;
}


.arm-period-item {
    flex: 1;

    min-height: 48px;

    padding: 8px 12px;

    display: flex;
    flex-direction: column;
    justify-content: center;

    border-left: 1px solid #dedede;
}


.arm-period-item:last-child {
    border-left: none;
}


.arm-period-label {
    color: #777777;

    font-size: 8px;
    font-weight: 600;

    margin-bottom: 2px;
}


.arm-period-item strong {
    color: #111111;

    font-size: 10px;
    font-weight: 700;
}


/* =========================================================
   SECTION
   ========================================================= */

.arm-section {
    margin-top: 17px;
}


.arm-section-heading {
    display: flex;

    align-items: center;

    gap: 8px;

    margin-bottom: 9px;

    color: #111111;

    font-size: 11px;
    font-weight: 800;
}


.arm-section-line {
    display: inline-block;

    width: 4px;
    height: 16px;

    background: #111111;

    border-radius: 2px;
}


/* =========================================================
   EMPLOYEE INFORMATION
   ========================================================= */

.arm-info-grid {
    display: grid;

    grid-template-columns: 1fr 1fr;

    border: 1px solid #dedede;

    border-radius: 6px;

    overflow: hidden;
}


.arm-info-card {
    min-height: 53px;

    padding: 8px 12px;

    background: #ffffff;

    border-left: 1px solid #e4e4e4;
    border-bottom: 1px solid #e4e4e4;
}


.arm-info-card:nth-child(even) {
    border-left: none;
}


.arm-info-card:nth-last-child(-n+2) {
    border-bottom: none;
}


.arm-info-label {
    margin-bottom: 3px;

    color: #858585;

    font-size: 8px;
    font-weight: 600;
}


.arm-info-value {
    color: #111111;

    font-size: 10px;
    font-weight: 700;

    min-height: 15px;
}


/* =========================================================
   WORK STATS
   ========================================================= */

.arm-stats-grid {
    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 7px;
}


.arm-stat-card {
    min-height: 72px;

    padding: 9px;

    border: 1px solid #dedede;

    border-radius: 6px;

    background: #ffffff;

    text-align: center;
}


.arm-stat-label {
    color: #666666;

    font-size: 8px;
    font-weight: 600;

    line-height: 1.4;
}


.arm-stat-value {
    margin-top: 4px;

    color: #111111;

    font-size: 17px;
    font-weight: 800;

    line-height: 1.1;
}


.arm-stat-en {
    margin-top: 4px;

    color: #999999;

    font-size: 6.5px;
    font-weight: 600;

    letter-spacing: .5px;

    direction: ltr;
}


.arm-stat-dark {
    background: #111111;

    border-color: #111111;
}


.arm-stat-dark .arm-stat-label,
.arm-stat-dark .arm-stat-value,
.arm-stat-dark .arm-stat-en {
    color: #ffffff;
}


/* =========================================================
   PAYMENTS
   ========================================================= */

.arm-payments-grid {
    display: grid;

    grid-template-columns: 1fr 1fr;

    gap: 10px;
}


.arm-payment-box {
    border: 1px solid #dcdcdc;

    border-radius: 7px;

    overflow: hidden;

    background: #ffffff;
}


/* =========================================================
   PAYMENT HEADER
   ========================================================= */

.arm-payment-header {
    display: flex;

    align-items: center;
    justify-content: space-between;

    min-height: 43px;

    padding: 7px 11px;

    background: #111111;

    color: #ffffff;
}


.arm-payment-title {
    display: block;

    font-size: 10px;
    font-weight: 800;

    color: #ffffff;
}


.arm-payment-subtitle {
    display: block;

    margin-top: 1px;

    font-size: 6.5px;
    font-weight: 600;

    color: #aaaaaa;

    letter-spacing: 1px;

    direction: ltr;
}


.arm-payment-symbol {
    display: flex;

    align-items: center;
    justify-content: center;

    width: 23px;
    height: 23px;

    border: 1px solid #555555;

    border-radius: 50%;

    color: #ffffff;

    font-size: 14px;
    font-weight: 400;
}


/* =========================================================
   PAYMENT TABLE
   ========================================================= */

.arm-payment-table {
    width: 100%;

    table-layout: fixed;

    background: #ffffff;
}


.arm-payment-table thead th {
    height: 29px;

    padding: 5px 8px;

    background: #f4f4f4;

    border-bottom: 1px solid #dedede;

    color: #555555;

    font-size: 7.5px;
    font-weight: 700;

    text-align: right;
}


.arm-payment-table tbody td {
    height: 31px;

    padding: 5px 8px;

    border-bottom: 1px solid #eeeeee;

    color: #222222;

    font-size: 8.5px;

    vertical-align: middle;
}


.arm-payment-table tbody tr:last-child td {
    border-bottom: none;
}


.arm-col-number {
    width: 32px !important;

    text-align: center !important;
}


.arm-col-amount {
    width: 100px !important;

    text-align: left !important;
}


.arm-row-number {
    text-align: center !important;

    color: #888888 !important;

    font-size: 7.5px !important;
}


.arm-component {
    font-weight: 600;
}


.arm-amount {
    text-align: left !important;

    direction: ltr;

    white-space: nowrap;

    font-weight: 700;

    font-variant-numeric: tabular-nums;
}


.arm-empty {
    height: 40px !important;

    text-align: center !important;

    color: #999999 !important;

    font-size: 8px !important;
}


/* =========================================================
   PAYMENT TOTAL
   ========================================================= */

.arm-payment-total {
    display: flex;

    align-items: center;
    justify-content: space-between;

    min-height: 42px;

    padding: 8px 11px;

    background: #f7f7f7;

    border-top: 1px solid #dedede;
}


.arm-payment-total span {
    color: #666666;

    font-size: 8px;
    font-weight: 600;
}


.arm-payment-total strong {
    color: #111111;

    font-size: 10px;
    font-weight: 800;

    direction: ltr;

    white-space: nowrap;
}


/* =========================================================
   SUMMARY
   ========================================================= */

.arm-summary {
    width: 48%;

    margin-top: 13px;

    margin-right: auto;

    border-top: 1px solid #dedede;
}


.arm-summary-row {
    display: flex;

    align-items: center;
    justify-content: space-between;

    min-height: 31px;

    padding: 5px 10px;

    border-bottom: 1px solid #eeeeee;
}


.arm-summary-row span {
    color: #666666;

    font-size: 8px;
    font-weight: 600;
}


.arm-summary-row strong {
    color: #111111;

    font-size: 9px;
    font-weight: 800;

    direction: ltr;

    white-space: nowrap;
}


/* =========================================================
   NET PAY
   ========================================================= */

.arm-net-pay {
    display: flex;

    align-items: center;
    justify-content: space-between;

    margin-top: 13px;

    min-height: 76px;

    padding: 12px 18px;

    background: #111111;

    border-radius: 7px;

    color: #ffffff;
}


.arm-net-pay-left {
    display: flex;

    flex-direction: column;

    justify-content: center;
}


.arm-net-label {
    font-size: 13px;
    font-weight: 800;

    color: #ffffff;
}


.arm-net-en {
    margin-top: 3px;

    font-size: 7px;
    font-weight: 600;

    letter-spacing: 1.5px;

    color: #999999;

    direction: ltr;
}


.arm-net-value {
    padding: 7px 12px;

    border: 1px solid #444444;

    border-radius: 4px;

    color: #ffffff;

    font-size: 19px;
    font-weight: 800;

    direction: ltr;

    white-space: nowrap;

    font-variant-numeric: tabular-nums;
}


/* =========================================================
   TOTAL IN WORDS
   ========================================================= */

.arm-words {
    display: flex;

    align-items: center;

    margin-top: 10px;

    padding: 9px 12px;

    background: #f7f7f7;

    border-right: 3px solid #111111;

    border-radius: 4px;
}


.arm-words-label {
    min-width: 90px;

    color: #555555;

    font-size: 8px;
    font-weight: 700;
}


.arm-words-value {
    flex: 1;

    color: #444444;

    font-size: 8px;

    line-height: 1.5;
}


/* =========================================================
   SIGNATURES
   ========================================================= */

.arm-signatures {
    display: grid;

    grid-template-columns: 1fr 1fr;

    gap: 80px;

    margin-top: 30px;

    padding: 0 30px;
}


.arm-signature {
    text-align: center;
}


.arm-signature-line {
    height: 1px;

    margin-bottom: 7px;

    background: #222222;
}


.arm-signature-title {
    color: #333333;

    font-size: 8px;
    font-weight: 700;
}


.arm-signature-en {
    margin-top: 2px;

    color: #999999;

    font-size: 6px;

    letter-spacing: .7px;

    direction: ltr;
}


/* =========================================================
   FOOTER
   ========================================================= */

.arm-footer {
    display: flex;

    justify-content: space-between;

    margin-top: 25px;

    padding-top: 8px;

    border-top: 1px solid #dddddd;

    color: #999999;

    font-size: 6.5px;

    direction: ltr;
}


/* =========================================================
   PAGE BREAK
   ========================================================= */

.arm-section,
.arm-payment-box,
.arm-net-pay,
.arm-summary {
    page-break-inside: avoid;
}


/* =========================================================
   PRINT
   ========================================================= */

@media print {

    html,
    body {
        background: #ffffff !important;
    }

    .print-format {
        padding: 0 !important;
        margin: 0 !important;

        background: #ffffff !important;
    }

    .arm-salary-slip {
        width: 100% !important;
        max-width: none !important;

        margin: 0 !important;
    }

    .arm-header {
        page-break-after: avoid;
    }

    .arm-payment-box {
        page-break-inside: avoid;
    }

    .arm-net-pay {
        page-break-inside: avoid;
    }

}


/* =========================================================
   ERPNext CLEANUP
   ========================================================= */

.print-format {
    padding: 0 !important;
    margin: 0 !important;
}


.print-format .print-heading {
    display: none !important;
}


.print-format .print-heading h2 {
    display: none !important;
}


.print-format hr {
    display: none !important;
}


.print-format .row {
    margin-left: 0 !important;
    margin-right: 0 !important;
}


.print-format [class*="col-"] {
    padding-left: 0 !important;
    padding-right: 0 !important;
}


/* =========================================================
   FORCE BLACK / WHITE
   ========================================================= */

.arm-salary-slip,
.arm-salary-slip * {
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}

.diagnostic-report {
    margin-top: 0px;
    padding-top: 0px;
    margin-right:15px;
	margin-left:15px;
}
.observation {
    page-break-inside: avoid;
	margin-bottom: 10px;
	border: 1px solid #dadce0;
	margin-right:15px;
	margin-left:15px;
	border-radius: 5px !important;
}

.grouped-obs {
	border: 1px solid #dadce0;
	font-size: 11px;
	padding-top: 5px;
	border-radius: 10px;
	margin-bottom: 5px;
	margin-left: 10px;
	margin-right: 10px;
}

.observation-details {
    page-break-inside: avoid;
	padding: 10px;
	display: -webkit-box;
	display: flex;
}

.note {
	padding-right: 15px;
	margin-left: 15px;
	text-align: left;
	padding-bottom: 3px;
}

.obs-first-line {
    font-size: 13px;
}

.ref-range {
    font-size: 12px !important;
}
.obs-second-line {
    font-size: 10px;
}

.obs-sh-first-line {
    font-size: 11px;
}

