css:
/* ========================== CSS ========================== */
@page { size: A4; margin: 15mm 15mm; }

.print-format {
    font-family: "Sultan Regular","Tahoma",Arial,sans-serif;
    direction: rtl;
    text-align: right;
    font-size: 12px;
    line-height: 1.5;
    color: #000;
    background: #fff;
}

/* رأس التقرير */
.report-header {
    text-align: center;
    margin-bottom: 15px;
    padding: 10px 0;
    border-bottom: 2px solid #333;
    background-color: #f5f5f5;
    border-radius: 8px;
}
.report-header .title {
    font-family: "Sultan Bold","Tahoma";
    font-size: 22px;
    font-weight: bold;
    color: #000;
    margin-bottom: 4px;
}
.report-header .sub-title {
    font-size: 14px;
    color: #555;
}

/* العناوين الفرعية */
.print-format h2, .print-format h3 {
    font-family: "Sultan Bold","Tahoma";
    font-weight: bold;
    color: #000;
    page-break-after: avoid;
}
.print-format h2 {
    font-size: 16px;
    margin: 18px 0 10px;
    padding: 8px 10px;
    background: #eef2f5;
    border-right: 4px solid #2c3e50;
    border-radius: 4px;
}
.print-format h3 {
    font-size: 13px;
    margin: 12px 0 6px;
    padding-right: 6px;
    border-right: 3px solid #3498db;
}

/* الأقسام */
.section-container { 
    page-break-inside: avoid; 
    margin-bottom: 12px;
}

/* صناديق المعلومات */
.info-box {
    margin-bottom: 12px;
    padding: 10px;
    background: #fff;
    border: 1px solid #ccc;
    border-radius: 6px;
}
.info-box span {
    display: inline-block;
    min-width: 130px;
    font-weight: bold;
    color: #222;
}

/* الجداول */
.print-format table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 12px;
    background-color: #fff;
    table-layout: fixed;
}
.print-format th {
    background: #f0f0f0;
    border: 1px solid #999;
    padding: 6px 4px;
    text-align: center;
    font-size: 12px;
    font-weight: bold;
    color: #000;
    vertical-align: middle;
}
.print-format td {
    border: 1px solid #bbb;
    padding: 5px 6px;
    vertical-align: top;
    word-wrap: break-word;
    overflow-wrap: break-word;
    font-size: 11.5px;
}
thead { display: table-header-group; }
tr { page-break-inside: avoid; }

/* Child Tables Headers */
.print-format table tbody tr:nth-child(odd) {
    background-color: #fcfcfc;
}
.print-format table tbody tr:nth-child(even) {
    background-color: #f9f9f9;
}

/* التوصيات والملاحظات */
.print-format .recommendations {
    margin-top: 8px;
    padding: 10px;
    background: #fbfbfb;
    border: 1px solid #ddd;
    border-right: 3px solid #27ae60;
    border-radius: 5px;
}
.print-format .recommendations ol, 
.print-format .recommendations ul,
.print-format ol,
.print-format ul {
    padding-right: 20px !important;
    padding-left: 0 !important;
    margin-right: 0;
    text-align: right;
    direction: rtl;
}
.print-format .recommendations li,
.print-format li {
    margin-bottom: 4px;
    line-height: 1.6;
}

/* تحسين عرض الحقول الكبيرة */
.print-format td span, .print-format td div {
    display: block;
    word-wrap: break-word;
}

/* فواصل الأعمدة (Column Break) */
.column-break {
    display: inline-block;
    width: 10px;
}

/* أحجام الخط للحقول الأساسية */
.print-format .info-box, .print-format td, .print-format th {
    font-size: 12px;
}

/* ========================= جداول فيما يخص الوقف ========================= */
.print-format .waqf-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 15px;
    table-layout: fixed;
}
.print-format .waqf-table th {
    background-color: #dce6f1;
    border: 1px solid #999;
    padding: 6px 4px;
    text-align: center;
}
.print-format .waqf-table td {
    border: 1px solid #bbb;
    padding: 5px 6px;
    text-align: center;
}

/* ========================= جداول فيما يخص القرآنية ========================= */
.print-format .quranic-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 15px;
    table-layout: fixed;
}
.print-format .quranic-table th {
    background-color: #f7e6d7;
    border: 1px solid #999;
    padding: 6px 4px;
    text-align: center;
}
.print-format .quranic-table td {
    border: 1px solid #bbb;
    padding: 5px 6px;
    text-align: center;
}

/* صفوف متناوبة للجداول الجديدة */
.print-format .waqf-table tbody tr:nth-child(odd),
.print-format .quranic-table tbody tr:nth-child(odd) {
    background-color: #fcfcfc;
}
.print-format .waqf-table tbody tr:nth-child(even),
.print-format .quranic-table tbody tr:nth-child(even) {
    background-color: #f9f9f9;
}

.print-format {
    direction: rtl;
    font-family: 'Tajawal', 'Cairo', system-ui, sans-serif;
    background-color: #ffffff;
}

.custom-survey-wrapper {
    color: #1e293b;
    font-size: 14px;
}

.survey-header-main {
    background: linear-gradient(135deg, #0f172a, #334155) !important;
    color: #ffffff !important;
    padding: 25px;
    text-align: center;
    border-radius: 12px;
    margin-bottom: 30px;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.company-title { font-size: 32px; font-weight: 900; margin-bottom: 8px; color: #f8fafc; }
.form-subtitle { font-size: 18px; font-weight: 500; color: #94a3b8; }

.main-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; align-items: stretch; margin-bottom: 25px; }
.grid-2-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 15px;}
.grid-3-cols { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }

.survey-section {
    background: #ffffff;
    border-radius: 16px;
    margin-bottom: 25px;
    border: 1px solid #e2e8f0;
    display: flex;
    flex-direction: column;
    break-inside: avoid; /* لتجنب قطع القسم بين صفحتين أثناء الطباعة */
}

.section-title {
    background-color: #eff6ff !important; color: #2563eb !important; padding: 12px 20px; font-size: 16px;
    font-weight: 700; display: inline-block; border-radius: 0 0 0 12px;
    border-bottom: 2px solid #bfdbfe; border-left: 2px solid #bfdbfe; align-self: flex-start;
    -webkit-print-color-adjust: exact;
}

.section-title.right-badge {
    border-radius: 0 12px 0 0; border-left: none; border-right: 2px solid #bfdbfe; align-self: flex-end;
}

.section-content { padding: 25px; flex-grow: 1; display: flex; flex-direction: column; }

.form-row-custom { display: flex; align-items: center; margin-bottom: 15px; }
.form-row-custom label { flex: 1; font-weight: 600; color: #475569; margin: 0; font-size: 14px; }

/* بديل الـ Inputs في الطباعة ليظهر كحقل معبأ */
.print-val {
    flex: 2; 
    background: #f8fafc !important; 
    border: 1px solid #cbd5e1; 
    border-radius: 8px;
    padding: 10px 15px; 
    color: #0f172a; 
    width: 100%; 
    box-sizing: border-box;
    min-height: 42px;
    -webkit-print-color-adjust: exact;
}
.textarea-val { min-height: 80px; white-space: pre-wrap; }

.checkbox-group { display: flex; flex-direction: column; gap: 12px; background: #f8fafc !important; padding: 15px; border-radius: 8px; border: 1px solid #e2e8f0; -webkit-print-color-adjust: exact;}
.checkbox-group.horizontal { flex-direction: row; gap: 25px; background: transparent !important; padding: 0; border: none; }
.checkbox-custom { display: flex; align-items: center; font-weight: 500; color: #334155; }
.checkbox-custom input[type="radio"] {
    -webkit-appearance: none; appearance: none; background-color: #fff !important; margin-left: 10px;
    width: 18px; height: 18px; border: 2px solid #cbd5e1; border-radius: 50%;
    display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0;
    -webkit-print-color-adjust: exact;
}
.checkbox-custom input[type="radio"]:checked { border-color: #2563eb; }
.checkbox-custom input[type="radio"]:checked::before {
    content: ""; width: 8px; height: 8px; border-radius: 50%; background-color: #2563eb !important;
    -webkit-print-color-adjust: exact;
}

.section-subtitle { text-align: center; margin-bottom: 20px; color: #64748b; font-weight: 700; font-size: 15px; position: relative; }
.section-subtitle::after { content: ""; display: block; width: 50px; height: 3px; background: #cbd5e1 !important; margin: 8px auto 0; border-radius: 2px; -webkit-print-color-adjust: exact;}
hr.modern-divider { border: none; height: 1px; background: linear-gradient(to right, transparent, #cbd5e1, transparent) !important; margin: 25px 0; -webkit-print-color-adjust: exact;}

/* تنسيق الجداول في الطباعة */
.child-table-placeholder { margin: 10px 0 20px 0; }
.table-custom { width: 100%; border-collapse: collapse; font-size: 13px; background: #fff; }
.table-custom th, .table-custom td { border: 1px solid #cbd5e1; padding: 8px 12px; text-align: right; }
.table-custom th { background-color: #f1f5f9 !important; color: #475569; font-weight: 700; -webkit-print-color-adjust: exact; }
.empty-table { background: #f8fafc !important; border: 1px dashed #cbd5e1; padding: 15px; text-align: center; color: #94a3b8; border-radius: 8px; -webkit-print-color-adjust: exact; }

.tech-block {
    direction: rtl;
    font-family: 'Segoe UI', Tahoma, Arial, sans-serif;
    line-height: 1.8;
    color: #000;
    position: relative;
}

/* الإشاري + التاريخ */
.reference-section {
    text-align: left;
    font-size: 13px;
    margin-bottom: 5px;
    padding-left: 5px;
}

.document-title {
    text-align: center;
    font-size: 24px;
    font-weight: bold;
    color: #000;
    border-top: 2px solid #000;
    border-bottom: 2px solid #000;
    padding: 15px 0;
    margin-bottom: 30px;
}

.client-details {
    border: 1px solid #e0e0e0;
    border-right: 4px solid #000;
    padding: 15px 20px;
    margin-bottom: 35px;
    background: #f9f9f9;
}

.client-details p {
    margin: 8px 0;
    font-size: 15px;
}

.client-details strong {
    display: inline-block;
    min-width: 160px;
}

.quotation-section {
    margin-bottom: 40px;
}

.tech-content-body {
    position: relative;
    overflow-x: hidden;
    padding-left: 20px;
}

/* تنسيق العناوين السوداء */
.tech-content-body h1,
.tech-content-body h2,
.tech-content-body h3,
.tech-content-body h4,
.tech-content-body h5,
.tech-content-body h6 {
    position: relative !important;
    display: inline-block !important;
    background: #000 !important;
    color: #fff !important;
    padding: 8px 18px !important;
    margin-top: 25px !important;
    margin-bottom: 15px !important;
    font-size: 18px !important;
    border-radius: 2px !important;
    z-index: 5 !important;
}

/* الخطوط المائلة */
.tech-content-body h1::before,
.tech-content-body h2::before,
.tech-content-body h3::before,
.tech-content-body h4::before,
.tech-content-body h5::before,
.tech-content-body h6::before {
    content: "";
    position: absolute !important;
    top: 0;
    right: 100%;
    width: 350px;
    height: 100%;
    background-image: repeating-linear-gradient(
        45deg,
        #000,
        #000 2px,
        transparent 2px,
        transparent 6px
    ) !important;
    z-index: -1;
}

.tech-content-body p {
    margin: 10px 0;
    text-align: justify;
}

.tech-content-body ul {
    padding-right: 25px;
    list-style-type: square;
}

html:
{%- if letter_head and not no_letterhead -%}
    {{ letter_head }}
{%- endif -%}

<div class="tech-block">

    <!-- الإشاري + التاريخ -->
    <div class="reference-section">
        <p style="margin: 0;">
            <strong>الإشاري:</strong> {{ doc.name }}
        </p>
        <p style="margin: 0;">
            <strong>التاريخ:</strong> {{ doc.get_formatted("التاريخ") }}
        </p>
    </div>

    <!-- العنوان الرئيسي -->
    <div class="document-title">
        العرض الفني والمالي
    </div>

    <!-- بيانات العميل -->
    <div class="client-details">
        <p>
            <strong>اسم العميل:</strong>
            {{ doc.customer_name or "" }}
        </p>

        <p>
            <strong>عنوان العرض الفني:</strong>
            {{ doc.project_name or "" }}
        </p>
    </div>

    <!-- محتوى العرض الفني -->
    <div class="quotation-section">
        <div class="tech-content-body">

            {% set content = doc.ardtxt or "" %}

            {# استبدال المتغيرات الرئيسية #}
            {% set content = content.replace("{{customer_name}}", (doc.customer_name or "")) %} 
            {% set content = content.replace("{{project_name}}", (doc.project_name or "")) %} 
            {% set content = content.replace("{{total_from}}", (doc.total_from or 0)|string) %} 
            {% set content = content.replace("{{total_to}}", (doc.total_to or 0)|string) %} 

            {# في حالة وجود Child Table يتم استخدام أول صف كمرجع للمتغيرات #}
            {% if doc.ard and doc.ard|length > 0 %}
                {% set first_row = doc.ard[0] %}
                {% set content = content.replace("{{land_area}}", (first_row.land_area or 0)|string) %} 
                {% set content = content.replace("{{price_from}}", (first_row.price_from or 0)|string) %} 
                {% set content = content.replace("{{price_to}}", (first_row.price_to or 0)|string) %} 
            {% endif %}

            {{ content | safe }}

        </div>
    </div>

</div>

{%- if footer and not no_letterhead -%}
    {{ footer }}
{%- endif -%}

css:
/* =========================================================
   ARM ARCHITECTURE & CONSTRUCTION
   CORPORATE LETTER FORMAT
   ERPNext v15 / wkhtmltopdf SAFE
   ========================================================= */


/* =========================================================
   PAGE
   ========================================================= */

@page {
    size: A4 portrait;
    margin: 14mm 15mm 12mm 15mm;
}


/* =========================================================
   GLOBAL RESET
   ========================================================= */

html,
body,
.print-format,
.print-format-preview {
    margin: 0 !important;
    padding: 0 !important;
    background: #ffffff !important;
}

body {
    font-family:
        "DejaVu Sans",
        "Tahoma",
        "Arial",
        sans-serif !important;

    color: #1f2937 !important;
    background: #ffffff !important;

    font-size: 10.5pt !important;
    line-height: 1.8 !important;

    direction: rtl !important;

    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}


/* =========================================================
   MAIN CONTAINER
   ========================================================= */

.arm-letter {
    width: 100%;
    margin: 0;
    padding: 0;

    direction: rtl;
    text-align: right;

    font-family:
        "DejaVu Sans",
        "Tahoma",
        "Arial",
        sans-serif;

    color: #1f2937;
    font-size: 10.5pt;
    line-height: 1.8;
}


/* =========================================================
   BOX SIZING
   ========================================================= */

.arm-letter *,
.arm-letter *:before,
.arm-letter *:after {
    box-sizing: border-box;
}


/* =========================================================
   HEADER
   ========================================================= */

.arm-header {
    width: 100%;

    margin: 0 0 0 0;
    padding: 0 0 10px 0;

    border-bottom: 2px solid #111827;

    page-break-inside: avoid;
    break-inside: avoid;
}


.arm-header-table {
    width: 100%;

    border-collapse: collapse;
    border-spacing: 0;

    table-layout: fixed;
}


.arm-header-table td {
    border: none !important;
    padding: 0 !important;

    vertical-align: middle;
}


/* Company side */

.arm-company {
    width: 82%;

    text-align: right;

    padding-right: 2px !important;
}


.company-name-ar {
    margin: 0;

    color: #111827;

    font-size: 18pt;
    font-weight: 800;

    line-height: 1.25;
}


.company-name-en {
    margin-top: 2px;

    color: #64748b;

    font-family: Arial, sans-serif;

    font-size: 7.5pt;
    font-weight: 700;

    letter-spacing: 1.8px;

    direction: ltr;
    text-align: right;
}


.company-department {
    margin-top: 5px;

    color: #475569;

    font-size: 8.5pt;
}


/* Logo */

.arm-logo-cell {
    width: 18%;

    text-align: left;

    direction: ltr;
}


.arm-logo {
    width: 58px;
    height: 58px;

    object-fit: contain;

    display: inline-block;

    border: none;
}


/* =========================================================
   DOCUMENT INFORMATION BAR
   ========================================================= */

.document-info {
    width: 100%;

    margin: 0 0 20px 0;

    border-bottom: 1px solid #d1d5db;

    background: #f8fafc;

    page-break-inside: avoid;
}


.info-table {
    width: 100%;

    border-collapse: collapse;
    border-spacing: 0;

    table-layout: fixed;
}


.info-table td {
    border: none !important;

    border-left: 1px solid #d1d5db !important;

    padding: 7px 9px !important;

    vertical-align: middle;

    text-align: right;
}


.info-table td:first-child {
    border-right: none !important;
}


.info-table td:last-child {
    border-left: none !important;
}


.info-cell {
    font-size: 8.5pt;

    white-space: nowrap;
}


.info-label {
    color: #64748b;

    font-weight: 500;

    margin-left: 5px;
}


.info-value {
    color: #111827;

    font-weight: 700;
}


.ltr {
    direction: ltr;
    unicode-bidi: embed;
}


.priority-cell {
    text-align: center !important;
}


.priority {
    display: inline-block;

    padding: 1px 7px;

    background: #e5e7eb;

    color: #374151;

    border-radius: 2px;

    font-size: 8pt;

    font-weight: 700;
}


.priority.urgent {
    background: #111827;

    color: #ffffff;
}


/* =========================================================
   RECIPIENT
   ========================================================= */

.recipient-section {
    margin: 0 0 18px 0;

    page-break-inside: avoid;
    break-inside: avoid;
}


.recipient-row {
    margin-bottom: 5px;

    font-size: 11.5pt;

    color: #111827;
}


.recipient-label {
    color: #64748b;

    font-weight: 500;

    margin-left: 7px;
}


.recipient-name {
    color: #111827;

    font-weight: 700;
}


.recipient-department {
    color: #64748b;

    font-size: 9.5pt;

    margin-right: 5px;
}


.salutation {
    color: #374151;

    font-size: 10pt;

    margin-top: 5px;
}


/* =========================================================
   SUBJECT
   ========================================================= */

.subject-box {
    width: 100%;

    display: table;

    margin: 0 0 24px 0;

    border: 1px solid #d1d5db;

    background: #ffffff;

    page-break-inside: avoid;
    break-inside: avoid;
}


.subject-label,
.subject-value {
    display: table-cell;

    vertical-align: middle;
}


.subject-label {
    width: 90px;

    background: #111827;

    color: #ffffff;

    padding: 8px 12px;

    font-size: 10pt;

    font-weight: 700;

    text-align: center;

    white-space: nowrap;
}


.subject-value {
    padding: 8px 14px;

    color: #111827;

    font-size: 10.5pt;

    font-weight: 700;

    text-align: right;
}


/* =========================================================
   LETTER BODY
   ========================================================= */

.letter-body {
    width: 100%;

    color: #1f2937;

    font-size: 10.5pt;

    line-height: 2;

    text-align: justify;

    text-justify: inter-word;

    margin: 0 0 25px 0;

    overflow-wrap: break-word;
}


/*
   The rich text coming from ERPNext may contain
   paragraphs, divs, lists, tables, etc.
*/

.letter-body p {
    margin: 0 0 14px 0;

    text-align: justify;

    orphans: 3;
    widows: 3;
}


.letter-body div {
    max-width: 100%;
}


.letter-body ul,
.letter-body ol {
    margin-top: 8px;
    margin-bottom: 15px;

    padding-right: 25px;
}


.letter-body li {
    margin-bottom: 5px;
}


.letter-body strong {
    color: #111827;
}


/* =========================================================
   ATTACHMENTS
   ========================================================= */

.attachments-section {
    margin-top: 20px;
    margin-bottom: 25px;

    page-break-inside: auto;
}


.section-heading {
    margin-bottom: 9px;

    padding-right: 9px;

    border-right: 3px solid #111827;

    color: #111827;

    font-size: 10.5pt;

    font-weight: 800;

    line-height: 1.4;

    page-break-after: avoid;
}


.attachments-table {
    width: 100%;

    border-collapse: collapse;

    table-layout: fixed;

    page-break-inside: auto;
}


.attachments-table thead {
    display: table-header-group;
}


.attachments-table tr {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}


.attachments-table th {
    background: #f3f4f6;

    color: #111827;

    font-size: 8.5pt;

    font-weight: 700;

    padding: 7px 8px;

    border-top: 1px solid #9ca3af;
    border-bottom: 1px solid #9ca3af;
    border-left: 1px solid #d1d5db;

    text-align: right;
}


.attachments-table th:first-child {
    border-right: 1px solid #d1d5db;
}


.attachments-table td {
    padding: 7px 8px;

    border-bottom: 1px solid #e5e7eb;
    border-left: 1px solid #e5e7eb;

    color: #374151;

    font-size: 8.5pt;

    vertical-align: middle;
}


.attachments-table td:first-child {
    border-right: 1px solid #e5e7eb;
}


.col-number {
    width: 11%;
}


.col-type {
    width: 14%;
}


.center {
    text-align: center !important;
}


/* =========================================================
   CLOSING
   ========================================================= */

.closing-section {
    margin-top: 35px;

    page-break-inside: avoid;
    break-inside: avoid;
}


.closing-text {
    margin-bottom: 28px;

    color: #374151;

    font-size: 10.5pt;

    font-weight: 500;
}


/* =========================================================
   SIGNATURES
   ========================================================= */

.signatures-table {
    width: 100%;

    border-collapse: collapse;

    table-layout: fixed;
}


.signatures-table td {
    border: none !important;

    padding: 0 !important;

    vertical-align: top;
}


.signature-column {
    width: 38%;

    text-align: center;
}


.signature-gap {
    width: 24%;
}


.signature-title {
    color: #111827;

    font-size: 9.5pt;

    font-weight: 700;

    margin-bottom: 10px;
}


.signature-space {
    height: 48px;

    margin: 0 18px 7px 18px;

    border-bottom: 1px solid #6b7280;
}


.signature-name {
    color: #111827;

    font-size: 9.5pt;

    font-weight: 700;
}


.signature-role {
    margin-top: 2px;

    color: #64748b;

    font-size: 8pt;
}


/* =========================================================
   FOOTER
   ========================================================= */

.arm-footer {
    margin-top: 25px;

    padding-top: 7px;

    border-top: 1px solid #9ca3af;

    color: #64748b;

    font-size: 7pt;

    text-align: center;

    direction: rtl;

    page-break-inside: avoid;
}


.footer-separator {
    margin: 0 7px;

    color: #cbd5e1;
}


/* =========================================================
   PAGE BREAK CONTROL
   ========================================================= */

.no-break {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}


.page-break {
    page-break-before: always !important;
    break-before: page !important;
}


/* =========================================================
   PRINT
   ========================================================= */

@media print {

    html,
    body {
        background: #ffffff !important;
    }

    .arm-letter {
        width: 100% !important;
    }

    .arm-header,
    .document-info,
    .recipient-section,
    .subject-box,
    .closing-section {
        page-break-inside: avoid !important;
    }

}

/* ============================================================
   ERPNext PRINT FORMAT
   ARD-QTN STYLE
   Safe for wkhtmltopdf
   ============================================================ */

.print-format {
    direction: rtl;
    text-align: right;
    font-family: Arial, Tahoma, sans-serif !important;
    color: #111111;
    background: #ffffff;
    font-size: 11px;
    line-height: 1.55;
    padding: 8px 18px 20px 18px;
}

/* ============================================================
   HEADER
   ============================================================ */

.header-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 5px;
}

.header-table td {
    border: none;
    vertical-align: middle;
}

/* الخلية الفارغة تأخذ المساحة المتبقية على اليمين */
.header-spacer {
    width: auto;
}

/* الحاوية اليسرى تجمع الشعار والنصوص بجانبه مباشرة */
.header-left-cluster {
    white-space: nowrap;
    text-align: left;
    direction: ltr; /* لتثبيت الشعار أقصى اليسار والنصوص على يمينه */
    width: auto;
}

.header-info {
    display: inline-block;
    vertical-align: middle;
    text-align: right;
    direction: rtl;
    font-size: 10.5px;
    line-height: 1.8;
    margin-right: 15px; /* مسافة فاصلة بين النصوص والشعار */
}

.logo-box {
    display: inline-block;
    vertical-align: middle;
}

.company-logo {
    display: block;
    max-width: 180px;
    max-height: 70px;
    width: auto;
    height: auto;
}
/* ============================================================
   HEADER LINES
   ============================================================ */

.black-line {
    width: 100%;
    height: 1.5px;
    background: #000000;
    margin: 5px 0;
}

/* ============================================================
   DOCUMENT TITLE
   ============================================================ */

.document-title {
    width: 100%;
    text-align: center;
    font-size: 18px;
    font-weight: bold;
    padding: 8px 0;
}

/* ============================================================
   PROJECT INFORMATION
   ============================================================ */

.project-info-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 15px;
    margin-bottom: 3px;
    background: #fafafa;
}

.project-info-table td {
    border: 1px solid #dddddd;
    padding: 6px 8px;
    vertical-align: middle;
}

.label-cell {
    width: 15%;
    font-weight: bold;
    background: #eeeeee;
    white-space: nowrap;
}

.value-cell {
    width: 35%;
    background: #ffffff;
}

/* ============================================================
   PROGRESS
   ============================================================ */

.progress-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 20px;
}

.progress-background {
    padding: 0 !important;
    height: 5px;
    background: #e5e5e5;
    border: none !important;
}

.progress-fill {
    height: 5px;
    background: #000000;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */

.section-header {
    width: 100%;
    border-collapse: collapse;
    margin-top: 20px;
    margin-bottom: 8px;
    page-break-after: avoid;
}

.section-header td {
    border: none;
    vertical-align: middle;
}

.section-title {
    width: 250px;
    background: #000000;
    color: #ffffff;
    font-size: 12px;
    font-weight: bold;
    padding: 6px 14px;
    text-align: right;
    white-space: nowrap;
}

.section-line-cell {
    width: auto;
    padding-right: 0;
}

.section-line {
    width: 100%;
    height: 1px;
    background: #cccccc;
}

/* ============================================================
   MAIN TABLE
   ============================================================ */

.report-table {
    width: 100%;
    border-collapse: collapse;
    border-spacing: 0;
    margin-bottom: 18px;
    table-layout: fixed;
}

.report-table thead {
    display: table-header-group;
}

.report-table th {
    background: #000000;
    color: #ffffff;
    border: 1px solid #000000;
    padding: 6px 5px;
    text-align: center;
    vertical-align: middle;
    font-size: 10px;
    font-weight: bold;
    line-height: 1.4;
}

.report-table td {
    border: 1px solid #d6d6d6;
    padding: 6px 5px;
    text-align: center;
    vertical-align: middle;
    font-size: 10px;
    line-height: 1.45;
}

.report-table tbody tr:nth-child(even) td {
    background: #f7f7f7;
}

.report-table tr {
    page-break-inside: avoid;
}

.task-name {
    text-align: right !important;
    font-weight: bold;
}

/* ============================================================
   INVOICE NUMBER
   ============================================================ */

.invoice-number {
    font-weight: bold;
    direction: ltr;
    text-align: center !important;
    word-break: break-word;
}

/* ============================================================
   FINANCIAL COLORS
   ============================================================ */

.paid {
    color: #065f46;
    font-weight: bold;
}

.outstanding {
    color: #991b1b;
    font-weight: bold;
}

/* ============================================================
   EMPTY MESSAGE
   ============================================================ */

.empty-message {
    text-align: center !important;
    color: #666666 !important;
    padding: 10px !important;
}

/* ============================================================
   APPROVAL
   ============================================================ */

.approval-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 30px;
    page-break-inside: avoid;
}

.approval-title {
    background: #000000;
    color: #ffffff;
    font-size: 12px;
    font-weight: bold;
    padding: 6px 12px;
    text-align: right;
    border: 1px solid #000000;
}

.signature-box,
.stamp-box {
    width: 50%;
    height: 100px;
    border: 1px solid #dddddd;
    padding: 12px;
    vertical-align: top;
    text-align: right;
}

.signature-box strong,
.stamp-box strong {
    font-size: 11px;
}

.stamp-box {
    text-align: center;
}

.stamp-placeholder {
    border: 1px dashed #999999;
    height: 55px;
    margin-top: 8px;
    padding-top: 15px;
    box-sizing: border-box;
    color: #888888;
    font-size: 9px;
}

/* ============================================================
   PRINT
   ============================================================ */

@media print {
    .print-format {
        padding: 5px 15px 15px 15px;
    }

    .report-table thead {
        display: table-header-group;
    }

    .report-table tr {
        page-break-inside: avoid;
    }

    .section-header {
        page-break-after: avoid;
    }

    .approval-table {
        page-break-inside: avoid;
    }
}
